#include "MistwatchRangerHut.h"
// 歷史木屋專屬命名空間；現行世界、發電機與遊戲來源仍使用正式版本。
namespace OriginalHutAsset {using namespace Mistwatch;}
#define Mistwatch OriginalHutAsset
#include "fixtures/hut-before-whole/MistwatchRangerHut.h"
#undef Mistwatch
namespace OldHut=OriginalHutAsset;
#include <bit>
#include <iostream>
#include <limits>
#include <stdexcept>

namespace {
using namespace Aevrynd;
using namespace Mistwatch;
std::size_t checks{};
void Check(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}
bool Same(float a,float b){return std::bit_cast<std::uint32_t>(a)==std::bit_cast<std::uint32_t>(b);}
bool SamePosition(const Vertex3D& a,const Vertex3D& b){return Same(a.x,b.x)&&Same(a.y,b.y)&&Same(a.z,b.z)&&a.normal==b.normal&&a.color==b.color;}
struct FirstHit {float fraction{std::numeric_limits<float>::infinity()};std::size_t firstIndex{std::numeric_limits<std::size_t>::max()};};
FirstHit FirstTriangle(const Mesh3D& mesh,Vec3 from,Vec3 to){FirstHit closest;const auto direction=to-from;for(std::size_t i=0;i<mesh.indices.size();i+=3){const auto point=[&](std::size_t at){const auto& v=mesh.vertices.at(mesh.indices.at(at));return Vec3{v.x,v.y,v.z};};const auto a=point(i),b=point(i+1),c=point(i+2),edge=b-a,other=c-a,h=Cross(direction,other);const float det=Dot(edge,h);if(std::abs(det)<1.e-7f)continue;const float inverse=1.f/det;const auto s=from-a;const float u=inverse*Dot(s,h);if(u<0||u>1)continue;const auto q=Cross(s,edge);const float v=inverse*Dot(direction,q),t=inverse*Dot(other,q);if(v>=0&&u+v<=1&&t>0&&t<1&&t<closest.fraction)closest={t,i};}return closest;}
const OldHut::RangerHutPart& PartAt(const std::vector<OldHut::RangerHutPart>& parts,std::size_t index){for(const auto& part:parts)if(index>=part.firstIndex&&index<part.firstIndex+part.indexCount)return part;throw std::runtime_error("First hit does not belong to actual authored range");}
void FirstFrame(const Mesh3D& mesh,const std::vector<OldHut::RangerHutPart>& parts,bool visible,OldHut::RangerHutPartKind expected,Vec3 sample,float side){const auto hit=FirstTriangle(mesh,{sample.x,sample.y,side*3.2f},{sample.x,sample.y,side*2.7f});Check(std::isfinite(hit.fraction),"Actual first frame ray must hit triangle");const auto& part=PartAt(parts,hit.firstIndex);Check(part.kind==(visible?expected:OldHut::RangerHutPartKind::Host),"First actual triangle range must be visible frame; old host must win negative control");if(visible){Check(std::abs(part.centre.x-sample.x)<1.e-5f,"First actual frame belongs to requested x range");Check(Same(part.centre.z,expected==OldHut::RangerHutPartKind::Sill?side*2.951f:side*2.958f),"First actual frame belongs to requested side");const float z=side*(3.2f-.5f*hit.fraction);Check(std::abs(z-side*(expected==OldHut::RangerHutPartKind::Sill?2.999f:2.994f))<1.e-5f,"First actual frame exterior plane");}}
}
int main(){try{
    using namespace Aevrynd;using namespace Mistwatch;
    constexpr std::array modes{OldHut::RangerHutArtMode::Baseline,OldHut::RangerHutArtMode::MaterialOnly,OldHut::RangerHutArtMode::TrimOnly,OldHut::RangerHutArtMode::Combined};
    std::array<Mesh3D,4> meshes;std::array<std::vector<OldHut::RangerHutPart>,4> parts;
    Material3D wood{{1,1,1,1},{.8f,0,0,.8f},true,MaterialTextureSetHandle3D{17},.5f};
    std::size_t uvTriangles{},firstFrameRays{},negativeHostRays{};
    for(std::size_t mode=0;mode<modes.size();++mode){const auto settings=OldHut::RangerHutArtSettingsFor(modes[mode]);meshes[mode]=OldHut::CreateRangerHut(settings,&parts[mode]);const auto& mesh=meshes[mode];Check(mesh.Valid()&&mesh.indices.size()==5124&&mesh.vertices.size()==3432,"All four actual modes retain indexed budget");std::size_t covered{};for(const auto& part:parts[mode]){Check(part.firstIndex==covered&&part.indexCount>0&&part.indexCount%3==0,"Actual part ranges are contiguous");covered+=part.indexCount;}Check(covered==mesh.indices.size(),"All actual first-hit ranges cover complete mesh");
        for(const auto& vertex:mesh.vertices){Check(Session::Finite({vertex.x,vertex.y,vertex.z})&&std::isfinite(vertex.u)&&std::isfinite(vertex.v),"All four actual modes finite positions/UV");Check(std::abs(vertex.x)<=2.5001f&&std::abs(vertex.z)<=3.0001f&&vertex.y>=-.00001f&&vertex.y<=3.8501f,"Original actual mesh bounds");if(settings.authoredUv){Check(vertex.u>=0&&vertex.u<=4.f&&vertex.v>=0&&vertex.v<=1.f,"Bounded authored UVs");const float band=std::floor(vertex.v*8.f)+.5f;Check(std::abs(vertex.v-band/8.f)<=.025001f,"Actual UV stays inside existing single siding central band");}}
        for(std::size_t i=0;i<mesh.indices.size();i+=3){const auto& a=mesh.vertices.at(mesh.indices.at(i));const auto& b=mesh.vertices.at(mesh.indices.at(i+1));const auto& c=mesh.vertices.at(mesh.indices.at(i+2));const double determinant=(double(b.u)-a.u)*(double(c.v)-a.v)-(double(b.v)-a.v)*(double(c.u)-a.u);Check(std::isfinite(determinant),"Actual triangle UV determinant finite");if(settings.authoredUv){Check(std::abs(determinant)>1.e-9,"Every authored box face and gable triangle has nondegenerate UV");++uvTriangles;}}
        for(const float side:{-1.f,1.f}){for(const float x:{-2.235f,-.075f,.075f,2.235f})for(const float y:{.95f,1.55f,2.15f}){FirstFrame(mesh,parts[mode],settings.visibleTrim,OldHut::RangerHutPartKind::Jamb,{x,y,0},side);settings.visibleTrim?++firstFrameRays:++negativeHostRays;}for(const float x:{-1.15f,1.15f}){FirstFrame(mesh,parts[mode],settings.visibleTrim,OldHut::RangerHutPartKind::Sill,{x,.858f,0},side);FirstFrame(mesh,parts[mode],settings.visibleTrim,OldHut::RangerHutPartKind::UpperFrame,{x,2.24f,0},side);if(settings.visibleTrim)firstFrameRays+=2;else negativeHostRays+=2;}}
        for(const bool noNormal:{false,true}){const auto material=OldHut::RangerHutMaterial(wood,settings,noNormal);Check(material.textures==wood.textures&&Same(material.surface.roughness,wood.surface.roughness)&&Same(material.surface.metallic,wood.surface.metallic)&&Same(material.surface.occlusion,wood.surface.occlusion)&&Same(material.surface.emissive,wood.surface.emissive)&&material.castsShadow==wood.castsShadow&&material.doubleSided==wood.doubleSided&&material.alphaMode==wood.alphaMode,"Hut material copy retains shared textures and original surface/state");Check(material.useUv==settings.authoredUv&&Same(material.textureScale,settings.authoredUv?1.f:.5f)&&Same(material.normalScale,noNormal?0.f:settings.authoredUv?.22f:1.f),"All four real mode materials and both normal branches match actual values");Check(!wood.useUv&&Same(wood.textureScale,.5f)&&Same(wood.normalScale,1.f),"Other wood source unchanged after hut material copy");}
    }
    const auto& baseline=meshes[0];for(std::size_t mode=1;mode<4;++mode)Check(meshes[mode].indices==baseline.indices,"Every comparison has exactly same topology/order");
    std::size_t movedVertices{},uvChangedVertices{};for(std::size_t i=0;i<baseline.vertices.size();++i){const auto& a=baseline.vertices[i];const auto& material=meshes[1].vertices[i];const auto& trim=meshes[2].vertices[i];const auto& combined=meshes[3].vertices[i];Check(SamePosition(a,material),"Material-only actual positions/normals/colours unchanged");Check(Same(a.u,trim.u)&&Same(a.v,trim.v),"Trim-only actual UV attributes unchanged");Check(SamePosition(trim,combined),"Combined real geometry exactly equals trim-only");if(!SamePosition(a,trim))++movedVertices;if(!Same(a.u,material.u)||!Same(a.v,material.v))++uvChangedVertices;}
    Check(movedVertices>0&&uvChangedVertices==3432,"Controls perform actual finite geometry and UV changes");
    for(const auto mode:modes){const auto settings=OldHut::RangerHutArtSettingsFor(mode);for(const auto& part:parts[static_cast<std::size_t>(mode)]){if(part.kind!=OldHut::RangerHutPartKind::Jamb&&part.kind!=OldHut::RangerHutPartKind::Sill&&part.kind!=OldHut::RangerHutPartKind::Roof)continue;const auto& mesh=meshes[static_cast<std::size_t>(mode)];if(!settings.authoredUv)continue;const auto first=part.firstIndex;const auto& a=mesh.vertices.at(mesh.indices.at(first));const auto& b=mesh.vertices.at(mesh.indices.at(first+1));const auto& c=mesh.vertices.at(mesh.indices.at(first+2));const std::array<Vertex3D,3> face{a,b,c};const bool vertical=part.kind==OldHut::RangerHutPartKind::Jamb;for(std::size_t left=0;left<face.size();++left)for(std::size_t right=left+1;right<face.size();++right){const auto& p=face[left];const auto& q=face[right];if(vertical&&Same(p.x,q.x)&&std::abs(p.y-q.y)>.1f)Check(std::abs(p.u-q.u)>.1f,"Jamb grain U follows true vertical axis");if(part.kind==OldHut::RangerHutPartKind::Sill&&Same(p.y,q.y)&&std::abs(p.x-q.x)>1.f)Check(std::abs(p.u-q.u)>.1f,"Sill grain U follows true horizontal axis");if(part.kind==OldHut::RangerHutPartKind::Roof&&std::abs(part.centre.z)>.1f&&std::abs(p.x-q.x)>1.f)Check(std::abs(p.u-q.u)>.1f,"Roof strip grain U follows rotated author long axis");}}}
    bool badMode=false;try{(void)OldHut::ParseRangerHutArtMode(L"invalid");}catch(const std::invalid_argument&){badMode=true;}Check(badMode,"Invalid real mode rejected");
    std::cout<<"HUT_MATERIAL_CPU_PASS hut_scope=historical checks="<<checks<<" modes=4 normal_branches=8 triangles_per_mode=1708 vertices_per_mode=3432 uv_triangles="<<uvTriangles<<" frame_first_rays="<<firstFrameRays<<" negative_host_rays="<<negativeHostRays<<" moved_vertices="<<movedVertices<<" uv_changed_vertices="<<uvChangedVertices<<" other_wood_unchanged=1 gpu_executed=0\n";return 0;
}catch(const std::exception& error){std::cerr<<"FIRST_DIVERGENCE checks="<<checks<<" error="<<error.what()<<'\n';return 1;}}
